const text = String(query ?? "").trim();

// Extract the heading and post.
const headingMatch = text.match(/^Heading:[ \t]*(.+)$/im);
const postMatch = text.match(/^Post:[ \t]*([\s\S]*)/im);

const heading = headingMatch?.[1]?.trim() ?? "";
const post = postMatch?.[1]?.trim() ?? "";

// Remove hashtags from word count.
const body = post
  .replace(/#[\p{L}\p{N}_]+/gu, "")
  .trim();

// Count words.
const wordCount = body
  ? body.split(/\s+/).filter(Boolean).length
  : 0;

const headingWordCount = heading
  ? heading.split(/\s+/).length
  : 0;

const hashtagCount =
  (post.match(/#[\p{L}\p{N}_]+/gu) ?? []).length;

// Validate requirements.
const errors = [];

if (!heading) {
  errors.push("Heading is missing");
}

if (!post) {
  errors.push("Post is missing");
}

if (headingWordCount < 5 || headingWordCount > 10) {
  errors.push("Heading must contain 5-10 words");
}

if (wordCount < 120 || wordCount > 150) {
  errors.push(
    `Post contains ${wordCount} words. Required: 120-150.`
  );
}

if (hashtagCount > 3) {
  errors.push("Maximum 3 hashtags allowed");
}

// Return a string, as required by the n8n tool.
return JSON.stringify({
  valid: errors.length === 0,
  word_count: wordCount,
  heading_word_count: headingWordCount,
  hashtag_count: hashtagCount,
  errors,
  instruction: errors.length === 0
    ? "VALID: Return this reviewed post."
    : "INVALID: Rewrite the post and call this tool again."
});
